  };

  // Add preference-specific ideal answers
  if (preference.includes('ativo')) {
    idealAnswers.penis_size = '18'; // example
    idealAnswers.likes_in_bottom = 'Bunda média';
    idealAnswers.sexual_intensity = 'Intenso e quente';
